example.text:
[
  { ci = true; }                                            # red default branches
  { search = "org:hausfold is:pr is:open"; }                 # the working queue
  {
    search = "org:hausfold is:pr is:open status:failure";    # …and the red half of it
    title = "red PRs";
    severity = "bad";
  }
]

{
  backup = {
    command = "/etc/haus/backup-status.sh";
    icon = "󰁯";
    interval = 300;
    permissions = [
      "full-disk-access"
    ];
    placement = "right";
  };
}

{
  recording = {
    description = "camera on, nothing interrupts";
    preventSleep = true;
    audio.input = "Studio Mic";
    apps.open = [ "OBS" ];
  };
}

{
  gst = "git status --short --branch"; # replace a built-in
  gsync = "git pull --rebase --autostash"; # add one
  gco = null; # remove one
}

[
  {
    key = "enter";
    command = "osascript -e 'tell application \"Things3\" to show quick entry panel'";
    caption = "Things Quick Entry";
  }
]

{
  "app:/Applications/Ghostty.app" = {
    hotkey = "opt+t";
  };
  "cmd:brew-services" = {
    listed = false;
  };
  "cmd:emoji" = {
    alias = "emo";
    hotkey = "opt+e";
  };
  "cmd:lane-here" = {
    workspaces = [
      "T"
    ];
  };
  "cmd:peek" = {
    bundleIds = [
      "com.mitchellh.ghostty"
    ];
  };
  "mode:clipboard" = {
    hotkey = "cmd+shift+v";
  };
  "shortcut:0ECC8F7A-3A52-467A-84C0-511CCE1CB9B7" = {
    alias = "shelf";
  };
}

{
  # Launcher app: leader s. Own workspace + pill come from putting
  # "slack" in a haus.workspaces entry's `apps` (see below).
  slack = {
    key = "s";
    name = "Slack";
    appId = "com.tinyspeck.slackmacgap";
    cask = "slack";
  };

  # Install-only: no key, so no leader binding and no pill.
  framer = { cask = "framer"; };
  orbstack = { package = pkgs.orbstack; };
  biome = { package = pkgs.biome; scope = "system"; };
  ical-buddy = { brew = "ical-buddy"; };
  xcode = { name = "Xcode"; appStoreId = 497799835; };
}

[
  {
    detect = "palette";
    hint = "Press {palette}, type tour, then hit ↵";
  }
]

{
  # Role workspace: three apps, one pill, one throw key.
  comms = {
    key = "c";
    icon = ":slack:";
    apps = [ "slack" "mail" "messages" ];
  };

  # Single-app workspace: the common case, one entry each.
  T = { key = "t"; icon = ":ghostty:"; apps = [ "ghostty" ]; };
}
